// cadres et ornements des cartes (planche fournie par l'utilisateur, fond transparent)
const FRAME_IMG = {
  card:'data:image/webp;base64,',
  card_g:'data:image/webp;base64,',
  oval:'data:image/webp;base64,',
  oval_g:'data:image/webp;base64,',
  ribbon:'data:image/webp;base64,',
  plaque:'data:image/webp;base64,',
  parch:'data:image/webp;base64,',
  banner:'data:image/webp;base64,',
  atk:'data:image/webp;base64,',
  hp:'data:image/webp;base64,',
  star:'data:image/webp;base64,',
  dragon:'data:image/webp;base64,',
};
// images injectées une seule fois : symboles SVG (#fr-oval, #fr-atk…) réutilisés par <use> ; côté CSS, frameCss() remplace chaque var(--fr-xxx) par l'URL
// (une variable CSS contenant une image entière serait re-analysée pour chaque carte à chaque rendu)
const frameCss = css => css.replace(/var\(--fr-([a-z-]+)\)/g, (m, k) => 'url(' + FRAME_IMG[k.replace('-', '_')] + ')');
const FRAME_DIM = { oval:[265, 377], oval_g:[280, 390], atk:[277, 340], hp:[267, 330], star:[297, 281], dragon:[287, 330], parch:[298, 234] };
(function () { try {
  const add = () => document.body.insertAdjacentHTML('afterbegin', '<svg width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs>' + Object.keys(FRAME_DIM).map(k => { const [w, h] = FRAME_DIM[k]; return `<symbol id="fr-${k.replace('_', '-')}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><image href="${FRAME_IMG[k]}" width="${w}" height="${h}" preserveAspectRatio="none"/></symbol>`; }).join('') + '<clipPath id="fr-clip"><ellipse cx="50" cy="56.2" rx="37.6" ry="45.4"/></clipPath></defs></svg>');
  if (document.body) add(); else document.addEventListener('DOMContentLoaded', add);
} catch (e) {} })();
